/**
 * <p>Rotates the elements in the array to the right (cyclically) by the given distance.</p>
 * <p>Example: <code>ArrayUtils.rotate([1, 2, 3, 4, 5], 2)</code> will give <code>[3, 4, 5, 1, 2]</code></p>
 * @param array the array to rotate, may be <code>null</code>
 * @param distance the distance to rotate by
 * @return the rotated array, or <code>null</code> if the input array is <code>null</code>
 */
public static byte[] rotate(final byte[] array, int distance) {
    if (array == null) {
        return null;
    }
    distance = distance % array.length;
    if (distance < 0) {
        distance += array.length;
    }
    byte[] rotated = new byte[array.length];
    System.arraycopy(array, distance, rotated, 0, rotated.length - distance);
    System.arraycopy(array, 0, rotated, rotated.length - distance, distance);
    return rotated;
}
```
