/**
 * Puts an array of bytes into this byte vector. The byte vector is automatically enlarged if necessary.
 * @param byteArrayValue an array of bytes. May be {@literal null} to put {@code byteLength} nullbytes into this byte vector.
 * @param byteOffset index of the first byte of byteArrayValue that must be copied.
 * @param byteLength number of bytes of byteArrayValue that must be copied.
 * @return this byte vector.
 */
public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    // Step 1: Check for null values
    if (byteArrayValue == null) {
        throw new NullPointerException("Byte array cannot be null");
    }
    if (byteOffset < 0 || byteOffset >= byteArrayValue.length) {
        throw new IndexOutOfBoundsException("Byte offset out of bounds");
    }
    if (byteLength < 0 || (byteOffset + byteLength) > byteArrayValue.length) {
        throw new IndexOutOfBoundsException("Byte length out of bounds");
    }

    // Step 2: Calculate the number of bytes to copy
    int bytesToCopy = Math.min(byteArrayValue.length - byteOffset, byteLength);

    // Step 3: Check if the byte vector needs to be enlarged
    if (this.writerIndex + bytesToCopy > this.capacity) {
        int newCapacity = Math.max(this.initialCapacity, this.writerIndex + bytesToCopy);
        byte[] newBuffer = new byte[newCapacity];
        System.arraycopy(this.buffer, 0, newBuffer, 0, this.writerIndex);
        this.buffer = newBuffer;
        this.capacity = newCapacity;
    }

    // Step 4: Copy the bytes
    System.arraycopy(byteArrayValue, byteOffset, this.buffer, this.writerIndex, bytesToCopy);
    this.writerIndex += bytesToCopy;
    return this;
}

