public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null) {
        throw new IllegalArgumentException("String cannot be null");
    }
    if (session == null) {
        throw new IllegalArgumentException("WriteSession cannot be null");
    }
    if (lb == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }

    try {
        byte[] bytes = str.getBytes(StandardCharsets.UTF_8);
        lb.write(bytes);
    } catch (IOException e) {
        throw new RuntimeException("Failed to write UTF-8 bytes", e);
    }

    return lb;
}

public static LinkedBuffer writeUTF8(CharSequence str, WriteSession session, LinkedBuffer lb) throws Exception {
	if (str.length() == 0) {
		throw new IOException("Input string is empty.");
	}

	// Bounds check
	if (lb.writableBytes() < (str.length() * 3)) {
		throw new IOException("Buffer is not large enough to hold the encoded string.");
	}

	for (int i = 0; i < str.length(); i++) {
		char c = str.charAt(i);
		if ((c >= 0x0000 && c <= 0x007F)) {
			lb.writeByte((byte) c);
		} else if (c > 0x07FF) {
			lb.writeByte((byte) (0xE0 | ((c >> 12) & 0x0F)));
			lb.writeByte((byte) (0x80 | ((c >> 6) & 0x3F)));
			lb.writeByte((byte) (0x80 | (c & 0x3F)));
		} else {
			lb.writeByte((byte) (0xC0 | ((c >> 6) & 0x1F)));
			lb.writeByte((byte) (0x80 | (c & 0x3F)));
		}
	}

	return lb;
}

