/**
 * Writes the utf8-encoded bytes from the string into the  {@link LinkedBuffer}.
 */
public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session,final LinkedBuffer lb){
    // Early exit if the string is empty
    if (str.length() == 0) {
        return lb;
    }
    // Get the number of bytes required to encode the string
    final int byteCount = Charset.forName("UTF-8").encode(str, session.output(), session.output().position()).limit();
    // Allocate a new byte array to hold the encoded data
    final byte[] encoded = new byte[byteCount];
    // Write the encoded data into the LinkedBuffer
    lb.write(encoded, 0, byteCount);
    // Return the LinkedBuffer
    return lb;
}
