public static String substitute(String value, Properties props) {
  if (value == null || props == null) {
    throw new IllegalArgumentException("Null parameter(s) provided");
  }

  Pattern pattern = Pattern.compile("\\$\\{[^}]+\\}");
  Matcher matcher = pattern.matcher(value);

  StringBuffer buffer = new StringBuffer();
  while (matcher.find()) {
    String var = matcher.group(0).substring(2, matcher.group(0).length() - 1);
    if (props.containsKey(var)) {
      matcher.appendReplacement(buffer, props.getProperty(var));
    } else {
      matcher.appendReplacement(buffer, matcher.group(0));
    }
  }

  matcher.appendTail(buffer);
  return buffer.toString();
}

