    // Step 2: Get the value corresponding to the key
    String value = props.getProperty(key);

    // Step 3: Perform variable substitution on the value
    try {
        value = performVariableSubstitution(value, props);
    } catch (SubstitutionException e) {
        throw new SubstitutionException("Variable substitution failed for key '" + key + "'", e);
    }

    return value;
