public long readRawVarint64() throws IOException {
  // Read the first byte
  int firstByte = readByte();
  // Check if the most significant bit is set
  if ((firstByte & 0x80) == 0) {
    // If not, the variable integer is just the first byte
    return firstByte;
  }
  // If the most significant bit is set, the variable integer is the first byte plus the following bytes
  // Shift the first byte left and add the following bytes
  long value = firstByte & 0x7F;
  for (int i = 0; i < 7; i++) {
    int nextByte = readByte();
    if ((nextByte & 0x80) == 0) {
      value |= nextByte << (7 * i);
      return value;
    }
    value |= nextByte << (8 * i);
  }
  // If no following byte is found, throw an exception
  throw new IOException("Invalid Varint format");
}

