        throw new IllegalArgumentException("Tour must contain at least 2 edges");
    }
    if(tour.size() > graph.getVertexCount()){
        throw new IllegalArgumentException("Tour size must be less than or equal to the number of vertices in the graph");
    }

    // create a map of edges to vertices
    Map<E,V> edgeVertexMap = new HashMap<>();
    for(E edge : tour){
        if(!edgeVertexMap.contains(edge)){
            edgeVertexMap.put(edge, graph.getVertices(edge));
        }
    }

    // create a map of vertices to edges
    Map<V,Set<E>> vertexEdgeMap = new HashMap<>();
    for(V vertex : graph.getVertices()){
        Set<E> edges = new HashSet<>();
        for(E edge : edgeVertexMap.get(vertex)){
            edges.add(edge);
        }
        vertexEdgeMap.put(vertex, edges);
    }

    // create a map of edges to vertices in the tour
    Map<E,V> tourEdgeMap = new HashMap<>();
    for(E edge : tour){
        tourEdgeMap.put(edge, edgeVertexMap.get(edge));
    }

    // create a graph path
    GraphPath<V,E> path = new GraphPath<>();
    path.setStart(graph.getVertices().iterator().next());

    // traverse the tour and add vertices and edges to the path
    for(E edge : tour){
        V vertex = edgeVertexMap.get(edge);
        path.addEdge(edge);
        path.addVertex(vertex);
    }

