}

private List<Pair<List<Pair<Integer, Integer>>, E>> computeMinimalSeparators(Graph graph, Edge edge) {
    List<Pair<List<Pair<Integer, Integer>>, E>> minimalSeparators = new ArrayList<>();
    for (Edge otherEdge : graph.edgesOf(edge.getSource())) {
        if (otherEdge != edge && graph.hasEdgeConnecting(otherEdge.getSource(), otherEdge.getTarget())) {
            minimalSeparators.add(new Pair<>(new ArrayList<>(Collections.singleton(new Pair<>(otherEdge.getSource(), otherEdge.getTarget()))), otherEdge));
        }
    }
    for (Edge otherEdge : graph.edgesOf(edge.getTarget())) {
        if (otherEdge != edge && graph.hasEdgeConnecting(otherEdge.getSource(), otherEdge.getTarget())) {
            minimalSeparators.add(new Pair<>(new ArrayList<>(Collections.singleton(new Pair<>(otherEdge.getTarget(), otherEdge.getSource()))), otherEdge));
        }
    }
    return minimalSeparators;
}
